//! Repository for DunningAction entities
//!
//! Originally generated by metaphor-schema; now user-owned — declared under user_owned in
//! metaphor.codegen.yaml. The custom methods below hold the dunning SQL (4-layer rule).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<DunningAction, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use rust_decimal::Decimal;
use sqlx::{PgConnection, PgPool};
use uuid::Uuid;

use crate::domain::entity::DunningAction;

/// Table name for DunningAction entities
pub const TABLE_NAME: &str = "payment.dunning_actions";

/// Repository for DunningAction entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct DunningActionRepository(
    backbone_orm::GenericCrudRepository<DunningAction, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for DunningActionRepository {
    type Target = backbone_orm::GenericCrudRepository<DunningAction, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl DunningActionRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The exact row a dunning-action upsert writes. The service computes `level` and `action_type`
/// (via the `dunning_level(dpd)` escalation table) before handing the row to
/// [`DunningActionRepository::upsert_action`]; the row mirrors the raw column shape, with `level`
/// and `action_type` binding as `&str` and DB-side casts (`$7::dunning_level`, `$8::dunning_action_type`).
pub struct NewDunningActionRow<'a> {
    pub id: Uuid,
    pub company_id: Uuid,
    pub run_id: Uuid,
    pub invoice_ref: Uuid,
    pub invoice_kind: &'a str,
    pub party_id: Option<Uuid>,
    pub level: &'a str,
    pub action_type: &'a str,
    pub days_past_due: i32,
    pub outstanding_amount: Decimal,
}

/// Dunning-action SQL. Lives here (not in the service) per the module's 4-layer rule: services
/// orchestrate and own the unit of work, repositories hold the SQL.
impl DunningActionRepository {
    /// Idempotent action upsert (unique `invoice_ref + invoice_kind + level` fence).
    ///
    /// Takes the CALLER'S connection so each action commits with the run it belongs to. The caller
    /// has already bound the company on it (`bind_company_on`) — don't re-bind here. Returns the
    /// rows affected: the caller gates its `emitted` counter on this being > 0, so a re-run for the
    /// same invoice does not double-count.
    pub async fn upsert_action(
        &self,
        conn: &mut PgConnection,
        a: &NewDunningActionRow<'_>,
    ) -> Result<u64, sqlx::Error> {
        let res = sqlx::query(
            r#"INSERT INTO payment.dunning_actions
                 (id, company_id, run_id, invoice_ref, invoice_kind, party_id,
                  level, action_type, days_past_due, outstanding_amount)
               VALUES ($1, $2, $3, $4, $5, $6, $7::dunning_level, $8::dunning_action_type, $9, $10)
               ON CONFLICT (invoice_ref, invoice_kind, level) WHERE (metadata->>'deleted_at') IS NULL
               DO NOTHING"#,
        )
        .bind(a.id).bind(a.company_id).bind(a.run_id)
        .bind(a.invoice_ref).bind(a.invoice_kind).bind(a.party_id)
        .bind(a.level).bind(a.action_type).bind(a.days_past_due).bind(a.outstanding_amount)
        .execute(conn)
        .await?;
        Ok(res.rows_affected())
    }
}

backbone_core::impl_crud_repository!(DunningActionRepository, DunningAction, soft_delete);
